CREATE TABLE IF NOT EXISTS master_camera (id INTEGER PRIMARY KEY AUTOINCREMENT, area_location_id INTEGER, camera_code TEXT NOT NULL, camera_name TEXT NOT NULL, camera_status INTEGER NOT NULL DEFAULT 1, ip_address TEXT NOT NULL, stream_url TEXT NOT NULL, auth_type TEXT NOT NULL DEFAULT 'basic', username TEXT, password TEXT, installed_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME, created_by TEXT, updated_by TEXT, deleted_at DATETIME, deleted_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sqlite_master_camera_code_active ON master_camera(camera_code) WHERE deleted_at IS NULL;
